/bin/bash -lc "python - <<'PY'
import sympy as s
bx,by,cx,cy,kx,ky,lx,ly=s.symbols('bx by cx cy kx ky lx ly')
B=s.Matrix([bx,by]); C=s.Matrix([cx,cy]); K=s.Matrix([kx,ky]); L=s.Matrix([lx,ly])
def cr(u,v): return s.expand(u[0]*v[1]-u[1]*v[0])
def dt(u,v): return s.expand(u.dot(v))
def ae(u,v,w,z): return s.expand(cr(u,v)*dt(w,z)-dt(u,v)*cr(w,z))
E1=ae(K-B,-B,-C,L-C)
E2=ae(L-B,K-B,L-C/2,C/2)
E3=ae(L-C,K-C,B/2,K-B/2)
for i,E in enumerate((E1,E2,E3),1):
 print(i, s.Poly(E,bx,by,cx,cy,kx,ky,lx,ly).terms()[:8])
PY"

